<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/bootstrap.php';require_admin();
$fields=['cafe_name','page_title','meta_description','instagram','phone','address','footer_text','currency','public_menu_url'];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($fields as $key){$value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>500)throw new RuntimeException('یکی از متن‌ها بیش از حد طولانی است.');$q->execute([$key,$value]);}$q->execute(['show_unavailable',request_bool('show_unavailable')?'1':'0']);$pdo->commit();flash('success','تنظیمات ذخیره شد.');redirect('admin/settings.php');}catch(Throwable $e){$pdo->rollBack();$error=$e->getMessage();}}
$s=settings_all();$adminTitle='تنظیمات سایت';require __DIR__.'/_header.php';
?><?php if(!empty($error)):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="panel edit-form"><?=csrf_field()?><div class="form-grid"><label>نام کافه<input name="cafe_name" maxlength="150" value="<?=e($s['cafe_name']??'میرا کافه')?>"></label><label>عنوان صفحه<input name="page_title" maxlength="160" value="<?=e($s['page_title']??'منوی میرا کافه')?>"></label><label class="wide">توضیح کوتاه برای موتورهای جستجو<textarea name="meta_description" maxlength="300" rows="2"><?=e($s['meta_description']??'')?></textarea></label><label>اینستاگرام<input name="instagram" dir="ltr" placeholder="miracafe" value="<?=e($s['instagram']??'')?>"></label><label>شماره تماس<input name="phone" dir="ltr" value="<?=e($s['phone']??'')?>"></label><label class="wide">آدرس<textarea name="address" maxlength="500" rows="2"><?=e($s['address']??'')?></textarea></label><label class="wide">آدرس نهایی منو برای QR<input name="public_menu_url" dir="ltr" placeholder="https://example.com" value="<?=e($s['public_menu_url']??'')?>"><small>پس از اتصال دامنه وارد کنید؛ اگر خالی باشد آدرس فعلی استفاده می‌شود.</small></label><label>متن پایین صفحه<input name="footer_text" value="<?=e($s['footer_text']??'با عشق برای شما ☕️')?>"></label><label>واحد پول<input name="currency" value="<?=e($s['currency']??'تومان')?>" readonly></label></div><label class="check option-line"><input type="checkbox" name="show_unavailable" <?=($s['show_unavailable']??'1')==='1'?'checked':''?>> محصولات ناموجود همچنان در منو دیده شوند</label><div class="form-actions"><button class="btn primary">ذخیره تنظیمات</button></div></form><?php require __DIR__.'/_footer.php';?>
